#!/usr/bin/env python3
"""Check exact native data-page protection, including real host access faults."""
import hashlib,importlib.util,json,pathlib,subprocess
R=pathlib.Path(__file__).resolve().parents[1];out=R/'generated/native-win32/virtual-protect/macos';out.mkdir(parents=True,exist_ok=True);report=out/'result.json';report.write_text('{"pass":false,"state":"running"}\n')
spec=importlib.util.spec_from_file_location('bindings',R/'scripts/gen-win32-bindings.py');g=importlib.util.module_from_spec(spec);spec.loader.exec_module(g);bindings=R/'port/llasm-runtime/win32-bindings.json';wrapper=out/'bindings.ll';wrapper.write_text(g.generate({'VirtualProtect':json.loads(bindings.read_text())['VirtualProtect']},False))
sources=[R/'port/core'/(n+'.c') for n in ['guest_address_space','guest_virtual_memory','process_heap','guest_heap']]+[R/'tests/virtual_protect_test.c',R/'tests/fixtures/native_enter.ll',wrapper];exe=out/'test'
subprocess.run(['clang','-target','arm64-apple-macos12','-O2','-pthread','-DPTROFS_64BIT','-Wall','-Wextra','-Werror','-Wno-override-module']+list(map(str,sources))+['-o',str(exe)],check=True)
run=subprocess.run([str(exe)],capture_output=True,text=True,timeout=30);(out/'run.log').write_text(run.stdout+run.stderr);assert run.returncode==0 and run.stdout.startswith('PASS:') and not run.stderr,(run.returncode,run.stdout,run.stderr)
checked=out/'checked';fixture=R/'generated/integration-review/guest-memory-pass/checked.o';fm=json.loads((fixture.parent/'result.json').read_text());assert hashlib.sha256(fixture.read_bytes()).hexdigest()==fm['checked_object_sha256']
subprocess.run(['clang','-target','arm64-apple-macos12','-O2','-pthread','-DPTROFS_64BIT','-DTB_CHECKED_SUBPAGES','-Wall','-Wextra','-Werror','-Wno-override-module']+list(map(str,sources))+[str(R/'port/core/guest_memory_checks.c'),str(fixture),'-o',str(checked)],check=True)
checked_run=subprocess.run([str(checked)],capture_output=True,text=True,timeout=30);(out/'checked-run.log').write_text(checked_run.stdout+checked_run.stderr);assert not checked_run.returncode and checked_run.stdout.startswith('PASS:') and checked_run.stderr.count('checked guest memory violation')==8,(checked_run.returncode,checked_run.stdout,checked_run.stderr)
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();report.write_text(json.dumps({'checked_output':checked_run.stdout.strip(),'checked_binary_sha256':sha(checked),'checked_fixture_sha256':sha(fixture),'checked_runtime_sha256':sha(R/'port/core/guest_memory_checks.c'),'pass':True,'state':'finished','output':run.stdout.strip(),'binary_sha256':sha(exe),'source_sha256':{str(p.relative_to(R)):sha(p) for p in sources+[pathlib.Path(__file__).resolve(),bindings,R/'scripts/gen-win32-bindings.py',R/'port/core/guest_address_space.h',R/'port/core/guest_memory_checks.h',R/'port/core/guest_system.h']},'scope':'Exact native data-page permissions for loader-owned static mappings. Opted-in software-checked subpages are exercised through emitted stores; default native-only mode still rejects subpages. Executable patch publication and dynamic arena protection fail explicitly; no Windows SEH equivalence.'},indent=2)+'\n');print(run.stdout.strip())
